from flask import Flask, request, jsonify
import pandas as pd
import joblib
import numpy as np
from datetime import datetime

# Initialize Flask App
app = Flask(__name__)

# Load Pre-Trained Models (Once at startup)
# These are generated by running prediction_model.py
try:
    model_au = joblib.load('rf_model_active_users.joblib')
    # model_sl = joblib.load('rf_model_single_session_users.joblib')
    # model_ml = joblib.load('rf_model_multi_session_users.joblib')
    print("Models loaded successfully!")
except Exception as e:
    print(f"Warning: Models not found. Please train models first. Error: {e}")

@app.route('/predict', methods=['GET'])
def get_prediction():
    """
    Example API Endpoint: http://127.0.0.1:5000/predict?date=2026-03-20
    """
    target_date_str = request.args.get('date')
    if not target_date_str:
        return jsonify({"error": "Please provide a date in YYYY-MM-DD format"}), 400

    try:
        # Generate 15-minute intervals for the requested date
        target_date = pd.to_datetime(target_date_str).date()
        intervals = pd.date_range(start=f"{target_date} 00:00", end=f"{target_date} 23:45", freq='15min')
        
        # Create a DataFrame for predictions
        df = pd.DataFrame({'Time Interval': intervals})
        df['Hour'] = df['Time Interval'].dt.hour
        df['DayOfWeek'] = df['Time Interval'].dt.dayofweek
        df['IsWeekend'] = df['DayOfWeek'].isin([5, 6])
        df['Month'] = df['Time Interval'].dt.month
        df['Day'] = df['Time Interval'].dt.day
        
        # Note: In a real system, you would dynamically check holidays here
        # using your load_holidays() function. For this API example, we assume False.
        df['IsHoliday'] = False
        df['IsOptionalHoliday'] = False

        # Advanced Time Encodings (as learned during backtesting)
        df['Hour_sin'] = np.sin(2 * np.pi * df['Hour']/23.0)
        df['Hour_cos'] = np.cos(2 * np.pi * df['Hour']/23.0)
        df['DayOfWeek_sin'] = np.sin(2 * np.pi * df['DayOfWeek']/6.0)
        df['DayOfWeek_cos'] = np.cos(2 * np.pi * df['DayOfWeek']/6.0)

        # To predict Active Users accurately, we need the SL, ML, AL cascades.
        # This requires the other 3 models. For simplicity in this demo, 
        # we assume you load them and run them.
        
        # FINAL PREDICTION (Example format)
        # predictions = model_au.predict(df[features])
        
        # Returning Dummy Data to show structure
        response_data = {
            "requested_date": target_date_str,
            "status": "success",
            "predictions": [
                {
                    "time": "09:00:00",
                    "predicted_active_users": 115,
                    "servers_needed": 3
                },
                {
                    "time": "09:15:00",
                    "predicted_active_users": 130,
                    "servers_needed": 4
                }
                # ... would contain all 96 intervals ...
            ]
        }
        
        return jsonify(response_data)
        
    except Exception as e:
        return jsonify({"error": str(e)}), 500

if __name__ == '__main__':
    # Runs the API Server on port 5000
    print("Prediction API Server running on port http://127.0.0.1:5000")
    app.run(debug=True, port=5000)
